#!/bin/sh

#cleanup
rm -rf obj_dir
rm -f f1_full.vcd

#connect Vbuddy
~/Documents/iac/lab0-devtools/tools/attach_usb.sh

# ensure read/write permissions on the serial port
sudo chmod 666 /dev/ttyUSB0

#run verilator to translate verilog into C++. including C++ testbench
verilator -Wall --cc --trace f1_full.sv f1_fsm.sv clktick.sv delay.sv lfsr.sv --top-module f1_full --exe f1_full_tb.cpp


#build c++ project via make automatically  generated by Verilator
make -j -C obj_dir/ -f Vf1_full.mk Vf1_full

#run executable simulation file
obj_dir/Vf1_full
